27:  *      otherwise) are:
28:  *    url {String} E.g. 'ldaps://ldap.example.com:663'
29:  *    adminDn {String} E.g. 'uid=myapp,ou=users,o=example.com'
30:  *    adminPassword {String} Password for adminDn.
31:  *    searchBase {String} The base DN from which to search for users by
32:  *        username. E.g. 'ou=users,o=example.com'
33:  *    searchFilter {String} LDAP search filter with which to find a user by
34:  *        username, e.g. '(uid={{username}})'. Use the literal '{{username}}'
35:  *        to have the given username be interpolated in for the LDAP
36:  *        search.
37:  *    log4js {Module} Optional. The require'd log4js module to use for logging.
38:  *        logging. If given this will result in TRACE-level logging for
39:  *        ldapauth.
40:  *    verbose {Boolean} Optional, default false. If `log4js` is also given,
41:  *        this will add TRACE-level logging for ldapjs (quite verbose).
42:  *    cache {Boolean} Optional, default false. If true, then up to 100
43:  *        credentials at a time will be cached for 5 minutes.
44:  *    timeout {Integer} Optional, default Infinity. How long the client should
45:  *        let operations live for before timing out.
46:  *    connectTimeout {Integer} Optional, default is up to the OS. How long the
47:  *        client should wait before timing out on TCP connections.
48:  *    tlsOptions {Object} Additional options passed to the TLS connection layer
49:  *        when connecting via ldaps://. See
50:  *        http://nodejs.org/api/tls.html#tls_tls_connect_options_callback
51:  *        for available options
52:  */
53: function LdapAuth(opts) {
54:   this.opts = opts;
55:   assert.ok(opts.url);
56:   assert.ok(opts.adminDn);
57:   assert.ok(opts.searchBase);
58:   assert.ok(opts.searchFilter);
59: 
60:   this.log = opts.log4js && opts.log4js.getLogger('ldapauth');
61: 
62:   if (opts.cache) {
63:     var Cache = require('./cache');
64:     this.userCache = new Cache(100, 300, this.log, 'user');
65:   }
66: 
67:   var clientOpts = {url: opts.url};
68:   if (opts.log4js && opts.verbose) {
69:     clientOpts.log4js = opts.log4js;
70:   }
71:   if (opts.timeout) {
72:     clientOpts.timeout = opts.timeout;
73:   }
74:   if (opts.connectTimeout) {
75:     clientOpts.connectTimeout = opts.connectTimeout;
76:   }
77:   if (opts.tlsOptions) {
78:     clientOpts.tlsOptions = opts.tlsOptions;
79:   }
80:   this._adminClient = ldap.createClient(clientOpts);
81:   this._adminBound = false;
82:   this._userClient = ldap.createClient(clientOpts);
83: 
84:   this._salt = bcrypt.genSaltSync();
85: }
