119:  * Find the user record for the given username.
120:  *
121:  * @param username {String}
122:  * @param callback {Function} `function (err, user)`. If no such user is
123:  *    found but no error processing, then `user` is undefined.
124:  *
125:  */
126: LdapAuth.prototype._findUser = function (username, callback) {
127:   var self = this;
128:   if (!username) {
129:     return callback("empty username");
130:   }
