176:  */
177: LdapAuth.prototype.authenticate = function (username, password, callback) {
178:   var self = this;
179: 
180:   if (self.opts.cache) {
181:     // Check cache. 'cached' is `{password: <hashed-password>, user: <user>}`.
182:     var cached = self.userCache.get(username);
183:     if (cached && bcrypt.compareSync(password, cached.password)) {
184:       return callback(null, cached.user)
185:     }
186:   }
187: 
188:   // 1. Find the user DN in question.
189:   self._findUser(username, function (err, user) {
190:     if (err)
191:       return callback(err);
192:     if (!user)
193:       return callback(format('no such user: "%s"', username));
194:     // 2. Attempt to bind as that user to check password.
195:     self._userClient.bind(user.dn, password, function (err) {
196:       if (err) {
197:         self.log && self.log.trace('ldap authenticate: bind error: %s', err);
198:         return callback(err);
199:       }
200:       if (self.opts.cache) {
201:         bcrypt.hash(password, self._salt, function (err, hash) {
202:           self.userCache.set(username, {password: hash, user: user});
203:           return callback(null, user);
204:         });
205:       } else {
206:         return callback(null, user);
207:       }
208:     });
209:   });
210: }
211: 
212: 
213: 
214: module.exports = LdapAuth;

